package com.nik.roadplayer

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap
import androidx.compose.ui.layout.ContentScale

enum class MerylBannerKind {
    CAR_AUDIO,
    MINI_STUDIO
}

@Composable
fun MerylBanner(
    kind: MerylBannerKind,
    modifier: Modifier = Modifier
) {
    val encoded = when (kind) {
        MerylBannerKind.CAR_AUDIO -> CAR_BANNER_BASE64
        MerylBannerKind.MINI_STUDIO -> STUDIO_BANNER_BASE64
    }
    val bitmap = remember(kind) {
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }
    bitmap?.let {
        Image(
            bitmap = it.asImageBitmap(),
            contentDescription = null,
            modifier = modifier,
            contentScale = ContentScale.Fit
        )
    }
}

private const val CAR_BANNER_BASE64 = ""
private const val STUDIO_BANNER_BASE64 = ""
